const lessonOrder=[14,12,0,1,2,3,4,5,6,13,7,8,10,11,9];
const lessonMinutes=[2,5,2,3,4,4,7,5,6,4,4,5,4,5,0];
const teacherGuides=[{"say":"Две команды пришли в одну переговорку. Обе считают, что забронировали её. Спроектируем приложение, в котором так не получится.","steps":["Покажи две команды.","Собери правила, не список классов.","Договоритесь о соседних встречах и отмене."],"qa":[{"q":"Что приложение разрешает?","a":"Создать бронь, посмотреть расписание, перенести и отменить свою бронь."},{"q":"Что оно запрещает?","a":"Пересечение активных броней одной комнаты, интервал с концом раньше начала и отмену чужой брони."},{"q":"Можно ли начать следующую встречу ровно в 11:00, если предыдущая закончилась в 11:00?","a":"Да. Это выбранное правило нашего приложения."}],"extra":"Не добавляй пока оплату, роли администратора и повторяющиеся встречи. Запиши их как возможное развитие.","sources":[]},{"say":"Договоримся о словах. Комната — место. Бронь — кто и когда занимает это место.","steps":["Раскрывай карточки после ответов.","Отдельно назови организатора и интервал."],"qa":[{"q":"Что хранит каждый объект?","a":"Room: номер, название, вместимость. Booking: номер брони, комната, организатор, интервал, статус. TimeInterval: начало и конец."},{"q":"Встречу отменили. Что произойдёт с бронью?","a":"Организатор отменяет её. Бронь остаётся в истории, но больше не занимает комнату."},{"q":"Нужен ли отдельный Meeting?","a":"Пока нет. Мы не ведём повестку и участников. Класс понадобится при появлении таких правил."}],"extra":"Полный User с профилем сейчас не нужен. В бронь передаём идентификатор организатора.","sources":[]},{"say":"Подвинем второй интервал. Посмотрим, когда две встречи можно разрешить.","steps":["Поставь 10:30: есть пересечение.","Поставь 11:00: пересечения нет.","После обсуждения покажи псевдокод."],"qa":[{"q":"10:00–11:00 и 11:00–12:00 пересекаются?","a":"Нет. Конец первого интервала не входит в занятое время."},{"q":"Как проверить пересечение?","a":"A.Start < B.End и B.Start < A.End. Оба условия должны выполняться."},{"q":"Где проверить начало и конец?","a":"При создании TimeInterval: Start должен быть меньше End."}],"extra":"На экране один день и одна временная зона. В настоящем приложении сравнивают полные моменты времени, а не только часы. Даты и часовые пояса тоже учитываются.","sources":[]},{"say":"Переносим бронь №42. Время изменилось, номер остался: это та же бронь.","steps":["Нажми перенос.","Сравни две одинаковые карточки интервалов."],"qa":[{"q":"Брони двух разных команд на одно время равны?","a":"Нет. У них разные номера. Их интервалы могут быть равны, сами брони — нет."},{"q":"Почему Booking — Entity?","a":"По идентификатору узнаём ту же бронь после изменения времени или статуса."},{"q":"Почему TimeInterval — Value Object?","a":"Нам важны начало и конец. Два интервала с одинаковыми полными границами взаимозаменяемы."},{"q":"Объект значения обязательно struct?","a":"Нет. Это смысл объекта. Он может быть классом или структурой."}],"extra":"record помогает получить равенство по значениям, но сам не проверяет правила и не гарантирует глубокую неизменяемость. Его свойства или вложенная коллекция могут изменяться.","sources":[["Records в C#","https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/record"]]},{"say":"Предложите классы. Для каждого скажем, какие данные и проверки ему нужны.","steps":["Раскрывай модель по одному объекту.","Покажи рамку расписания и его броней.","Покажи псевдокод Book."],"qa":[{"q":"Кто видит другие брони и проверяет пересечения?","a":"RoomSchedule. Отдельная Booking знает свой интервал, но не все остальные брони."},{"q":"Что делает Room?","a":"Хранит сведения о комнате. В нашем варианте правила занятости находятся в расписании."},{"q":"Что означает рамка?","a":"Изменения этих объектов согласовываем. Бронь создают и меняют через расписание."},{"q":"Что такое агрегат и его корень?","a":"Агрегат — группа объектов, чьи правила поддерживают вместе. Корень — объект, через который меняют группу. Здесь это RoomSchedule."},{"q":"Можно ли иначе?","a":"Да. Но нужно объяснить, кто видит другие брони и как сохранение защищает правило."}],"extra":"Агрегат не равен таблице и не требует загрузки всей истории. Данные выбирают для нужного периода, но все изменения комнаты используют общий механизм записи. Если делить расписания по дням, интервалы через полночь требуют отдельного решения. Коллекцию не выставляют как изменяемый List.","sources":[["Модель и агрегаты в .NET","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/microservice-domain-model"]]},{"say":"Появился бот. Он должен разрешать и запрещать те же брони, что и сайт.","steps":["Покажи дублирование слева.","Сравни с общими правилами справа."],"qa":[{"q":"Кто проверяет формат даты?","a":"Экран или входной API разбирает ввод. Сервер тоже проверяет его: доверять одной проверке в браузере нельзя."},{"q":"Кто проверяет свободное время?","a":"RoomSchedule. Это правило действует для любого интерфейса."},{"q":"Что будет при разных проверках?","a":"Бот разрешит бронь, которую сайт запрещает. Исправления придётся повторять."},{"q":"Почему не вынести всё в один сервис?","a":"Для сложных правил удобнее держать поведение у объектов с нужными данными. Для простого справочника более простое решение нормально."}],"extra":"Методы не нужны каждому классу ради DDD. Доменный сервис применяют, если правило нельзя естественно отнести к одному объекту. Application организует загрузку и сохранение; это другая ответственность.","sources":[["Когда нужна богатая модель","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/microservice-domain-model"]]},{"say":"Экран получает ввод. Действие приложения загружает расписание. Расписание проверяет бронь. Затем результат сохраняют.","steps":["Нажимай следующий этап.","Покажи псевдокод.","Затем перейди к зависимостям кода."],"qa":[{"q":"Добавили бота. Переписываем проверку занятости?","a":"Нет. Он вызывает то же действие и ту же модель."},{"q":"Что находится в UI?","a":"Экран или обработчик сообщения: ввод и результат."},{"q":"Что находится в Application?","a":"Действие «Забронировать»: загрузить расписание, вызвать Book, сохранить."},{"q":"Что находится в Domain?","a":"RoomSchedule, Booking, TimeInterval и их правила."},{"q":"Что находится в Infrastructure?","a":"Конкретная работа с базой и отправка сообщений."},{"q":"Это схема зависимостей?","a":"Нет. Здесь показан порядок выполнения запроса. Зависимости кода показаны отдельно."}],"extra":"actorId берётся из проверенной учётной записи, не из произвольного поля формы. Для начала хватит папок. Сценарий использует контракт сохранения; реализацию подключают при запуске.","sources":[["Слои DDD в .NET","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"]]},{"say":"Статус не записывают напрямую. Вызывают Cancel, который проверяет организатора.","steps":["Раскрой правило после ответов.","Покажи псевдокод отмены."],"qa":[{"q":"Что плохого в «статус = отменена» снаружи?","a":"Так можно обойти проверку организатора. Поэтому сеттер закрывают."},{"q":"Кто отменяет?","a":"Только организатор в нашей модели. Приложение передаёт идентификатор вошедшего пользователя."},{"q":"Что делать при повторной отмене?","a":"Мы выбрали повтор без изменения результата. Своя уже отменённая бронь не меняется."},{"q":"Где Cancel?","a":"Booking проверяет свои данные. В нашем варианте действие вызывают через RoomSchedule, чтобы сохранить изменение расписания."}],"extra":"Если администратору тоже разрешат отмену, это новое требование. Не вводим роли заранее. Отмена сохраняет историю, но убирает бронь из занятости.","sources":[]},{"say":"Оба запроса прочитали свободное время до первой записи. Поэтому обе проверки прошли.","steps":["Пройди три шага без защиты.","Включи проверку версии, пройди четыре шага.","Покажи псевдокод записи."],"qa":[{"q":"Почему «время свободно» недостаточно?","a":"Между проверкой и записью другой запрос может занять время."},{"q":"Зачем второй запрос читает снова?","a":"После отказа его данные устарели. Новая версия уже содержит первую бронь."},{"q":"Где версия?","a":"У общего расписания комнаты. Оба запроса должны изменять одну и ту же версию."},{"q":"Почему версия каждой новой брони не поможет?","a":"Это две разные записи. Они не обновляют одну строку и не конфликтуют между собой."},{"q":"Что значит атомарно?","a":"Проверка версии и запись — одна неделимая операция. Между ними нельзя вклиниться."}],"extra":"В БД обновляют строку RoomSchedule с условием Version = expectedVersion и записывают брони в той же транзакции. При нуле обновлённых строк откатывают. Добавление дочерней Booking само не обязано менять версию корня. EF Core проверяет token при UPDATE/DELETE; два разных INSERT так не защищены. Просто объявить token у Booking недостаточно.","sources":[["Конфликты версии в EF Core","https://learn.microsoft.com/en-us/ef/core/saving/concurrency"]]},{"say":"Бронь сохранилась. Сообщение не отправилось. В нашей модели комнату всё равно считаем занятой.","steps":["Бонус: пропусти, если прошёл час.","Покажи повторную отправку."],"qa":[{"q":"Ошибка сообщения отменяет бронь?","a":"В нашем приложении нет. В другом продукте может быть иное правило."},{"q":"Как не потерять задачу доставки?","a":"Записать бронь и задачу отправки в одной транзакции. Отдельный отправитель повторяет попытки."},{"q":"Сообщение придёт ровно один раз?","a":"Не обязательно. Повторы могут дать дубли. При необходимости нужна защита от повторной обработки."}],"extra":"Outbox — дополнительный приём работы с БД и сообщениями. Не обязательная часть DDD и не задание этой пары.","sources":[]},{"say":"Переносим встречу. Номер брони сохраняем. Новый интервал проверяем заново.","steps":["Нажми перенос на 12:00.","Собери проверки, потом раскрой подсказки."],"qa":[{"q":"Какие правила уже есть?","a":"Организатор, активный статус, корректный интервал, отсутствие пересечений."},{"q":"Какую операцию добавим?","a":"RoomSchedule.Reschedule(id, newInterval, actor). Проверяет другие брони и меняет интервал этой."},{"q":"Почему исключаем саму бронь?","a":"Иначе она будет мешать своему переносу. Проверяем другие активные брони."},{"q":"Что при занятом времени?","a":"Отказать и оставить старый интервал. Сначала проверять, затем менять."},{"q":"Версия при переносе нужна?","a":"Да. До записи другой запрос может изменить расписание."}],"extra":"Перенос в другую комнату затрагивает два расписания. Это отдельное требование, сейчас его не добавляем.","sources":[]},{"say":"Назовите классы и правила каждого. Сравним с ValueType и TaxiOrder.","steps":["Попроси объяснить одно правило от ввода до записи.","Свяжи модель с домашками."],"qa":[{"q":"Что узнаёте в ValueType?","a":"Равенство по содержимому. В задании сравнивают публичные свойства, поля не участвуют."},{"q":"Что узнаёте в TaxiOrder?","a":"Сам заказ проверяет допустимые действия. Снаружи не выставляют статус напрямую."},{"q":"Что делает репозиторий водителей?","a":"Выдаёт водителя по идентификатору. Заказ он не меняет."},{"q":"Что останется при замене сайта ботом?","a":"Правила и действие приложения. Поменяется ввод и вывод."},{"q":"DDD полностью нужен всегда?","a":"Нет. Он полезен для сложных меняющихся правил. Простому справочнику сложная модель может не понадобиться."}],"extra":"Основной маршрут — план на 60 минут с обсуждениями, не гарантия скорости группы. Если задержались, сокращай рассказ, а не совместный выбор классов. Бонус после итогов в час не входит.","sources":[]},{"say":"Uber группировал сервисы по задачам бизнеса. Shopify разделял одно приложение на модули. Границы нужны в обоих случаях.","steps":["Назови три области Uber: карта, тариф, подбор водителя.","Покажи модули Shopify.","Верни вопрос к нашим переговоркам."],"qa":[{"q":"Зачем Uber объединял сервисы?","a":"Чтобы другие команды обращались к понятной точке входа области вместо всех внутренних сервисов."},{"q":"Что здесь связано с DDD?","a":"Области бизнеса и правила их взаимодействия. Uber прямо пишет, что DOMA использует идеи DDD вместе с другими подходами."},{"q":"Нужен сервис каждому классу?","a":"Нет. Shopify показывает пользу границ внутри одного приложения."},{"q":"Это схема компаний сейчас?","a":"Нет. Это исторические разборы: Uber 2020, Shopify 2019 и ретроспектива 2024. Схемы на слайде — наши иллюстрации."},{"q":"Как это выглядит в обычной работе разработчика?","a":"Приходит требование: организатор может перенести встречу. Уточняем, кто организатор, можно ли переносить отменённую бронь и что делать при пересечении. Добавляем действие Reschedule в модель, проверяем правила тестами. Сайт и бот вызывают это действие, а не пишут каждый свою проверку."},{"q":"Какой практический результат?","a":"При изменении правила исправляем его в одном месте. Новые экраны используют ту же проверку. Команды меньше зависят от внутреннего устройства чужих модулей."}],"extra":"Uber описывает области карт, тарифа и подбора водителя. DOMA не синоним DDD. Shopify пишет о модулях заказов, доставки, товаров и счетов и о замене расчёта налогов после изоляции зависимостей. В 2024 компания подчёркивает: названия бизнес-областей не всегда совпадают с реальными зависимостями кода. Не обещаем, что это вся архитектура компаний в 2026 году.","sources":[["Uber Engineering, 2020","https://www.uber.com/us/en/blog/microservice-architecture/"],["Shopify Engineering, 2019","https://shopify.engineering/deconstructing-monolith-designing-software-maximizes-developer-productivity"],["Shopify: выводы 2024","https://shopify.engineering/a-packwerk-retrospective"]]},{"say":"Здесь стрелки показывают, какие части кода знают друг о друге. Это другая схема, не порядок запроса.","steps":["Прочитай подписи стрелок.","Покажи независимость Domain от базы."],"qa":[{"q":"Как сменить базу, не переписывая Booking и TimeInterval?","a":"Реализовать тот же контракт сохранения для другой базы. Правила останутся в Domain."},{"q":"Почему Infrastructure зависит от Domain?","a":"Сохранение знает типы и контракты модели. Booking при этом не зависит от EF Core."},{"q":"Как Application сохраняет?","a":"Вызывает контракт. Реализацию связывают при запуске."},{"q":"Где контракт репозитория?","a":"Здесь в Domain. Можно выбрать Application. Главное — не привязывать правила к конкретной базе."},{"q":"Почему в лекции стрелки могли быть другими?","a":"Там Infrastructure включает общие вспомогательные типы. Здесь это конкретные БД и интеграции. Состав слоя отличается."},{"q":"Нужны четыре проекта?","a":"Нет. Можно начать с папок. Проекты помогают жёстче контролировать ссылки."}],"extra":"Это один современный вариант организации с независимой моделью. Запуск приложения связывает реализации и не показан на схеме. DI подробно будет в следующих блоках.","sources":[["Зависимости слоёв в .NET","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"]]},{"say":"DDD — проектирование вокруг правил предметной области. Сначала выясняем, как работает бронирование, затем выражаем эти правила в модели и коде.","steps":["Прочитай определение.","Назови пример: нельзя занять одну комнату двумя встречами одновременно.","Перейди к примерам из рабочих систем."],"qa":[{"q":"Что значит предметная область?","a":"Та часть реальной работы, которую автоматизируем: например, бронирование комнат."},{"q":"Что DDD меняет в разработке?","a":"Обсуждаем правила с людьми, которые знают работу. Используем одинаковые слова в разговоре и коде. Помещаем правила в модель, чтобы сайт, бот и API применяли их одинаково."},{"q":"DDD — это обязательно микросервисы?","a":"Нет. Модель и отдельные области можно организовать внутри одного приложения."}],"extra":"Для простого справочника DDD может быть избыточным. Подход полезен, когда правил много, они меняются и ошибки в них дорого обходятся.","sources":[]}];
